CREATE FUNCTION pg_temp.fp() RETURNS TABLE(t text, n bigint, h text) LANGUAGE sql AS $$
  SELECT 'canonical_seeds (master)', count(*), md5(string_agg(md5(x::text), '' ORDER BY x::text)) FROM canonical_seeds x
  UNION ALL SELECT 'live '||x.course_code||' seeds', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_seeds x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'live '||x.course_code||' legos', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_legos x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'live '||x.course_code||' phrases', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_practice_phrases x WHERE x.course_code IN ('cym_n_for_eng','cym_s_for_eng') GROUP BY x.course_code
  UNION ALL SELECT 'weave drops '||x.course_code, count(*), md5(string_agg(md5(row(x.course_code, x.seed_number, x.reason, x.decided_by)::text), '' ORDER BY x.seed_number)) FROM course_seed_weave_drops x
    WHERE (x.course_code, x.seed_number) NOT IN (SELECT c, s FROM t_seeds) GROUP BY x.course_code
  UNION ALL SELECT 'sandbox '||x.course_code||' other seeds', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_seeds x
    WHERE x.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') AND (x.course_code, x.seed_number) NOT IN (SELECT c, s FROM t_seeds) GROUP BY x.course_code
  UNION ALL SELECT 'sandbox '||x.course_code||' other legos', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_legos x
    WHERE x.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') AND (x.course_code, x.seed_number) NOT IN (SELECT c, s FROM t_seeds) GROUP BY x.course_code
  UNION ALL SELECT 'sandbox '||x.course_code||' other phrases', count(*), md5(string_agg(md5(x::text), '' ORDER BY x.id)) FROM course_practice_phrases x
    WHERE x.course_code IN ('cym_nv2_for_eng','cym_sv2_for_eng') AND (x.course_code, x.seed_number) NOT IN (SELECT c, s FROM t_seeds) GROUP BY x.course_code
$$;
CREATE TEMP TABLE pre AS SELECT * FROM pg_temp.fp();
SELECT 'BEFORE' k, * FROM pre ORDER BY t;
DO $$ BEGIN
  IF to_regclass('backup_cym_newydd_wrthyn_565_seeds') IS NOT NULL THEN RAISE EXCEPTION 'already applied (backup_cym_newydd_wrthyn_565_seeds exists)'; END IF;
  IF EXISTS (SELECT 1 FROM course_enrollments WHERE course_id IN ('cym_nv2_for_eng','cym_sv2_for_eng')) THEN
    RAISE EXCEPTION 'a sandbox has enrollments: renumbering would move learners (PROGRESS RULE)'; END IF;
  IF EXISTS (SELECT 1 FROM t_seeds WHERE c NOT IN ('cym_nv2_for_eng','cym_sv2_for_eng')) THEN RAISE EXCEPTION 'a touched seed is outside the sandboxes'; END IF;
  IF (SELECT count(*) FROM snap n JOIN course_practice_phrases p ON p.id = n.id AND p.target_text = n.target_text AND p.version = n.version) <> (SELECT count(*) FROM snap) THEN
    RAISE EXCEPTION 'CHANGED UNDER US: a phrase this edits or moves is gone or was edited since the plan — re-plan'; END IF;
  IF EXISTS (SELECT 1 FROM course_seed_weave_drops WHERE course_code = 'cym_nv2_for_eng' AND seed_number = 15) THEN RAISE EXCEPTION 'N seed 15 is already dropped'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_seeds WHERE id = '477c31b9-5a84-4c8e-a273-5f647468ec0d' AND target_text = 'dw i newydd ddechrau cofio' AND known_text = 'I’ve just started to remember' AND version = 82) THEN RAISE EXCEPTION 'CHANGED UNDER US: N seed 15'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_seeds WHERE id = '9836018d-9c1c-41cf-94ef-04c71707a53e' AND target_text = 'fedri di ddeud rhywbeth arall wrtha i cyn i mi ateb?' AND known_text = 'can you tell me something else before I answer?' AND version = 2) THEN RAISE EXCEPTION 'CHANGED UNDER US: N seed 1250'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_seeds WHERE id = 'a43c0cd5-c224-4962-8865-98d1b3ca2063' AND target_text = 'dw i newydd ddechrau cofio' AND known_text = 'I’ve just started to remember' AND version = 26) THEN RAISE EXCEPTION 'CHANGED UNDER US: S seed 15'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_seeds WHERE id = 'd3a56ebc-2d51-4157-a310-0da1db35c704' AND target_text = 'dw i newydd ddechrau dysgu Cymraeg achos dw i’n meddwl bod hi’n ddiddorol' AND known_text = 'I’ve just started to learn Welsh because I think it’s interesting' AND version = 24) THEN RAISE EXCEPTION 'CHANGED UNDER US: S seed 29'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_seeds WHERE id = '3cd78abf-3826-4127-b705-588befe442bb' AND target_text = 'alli di ddweud rhywbeth arall wrtha i cyn i fi ateb?' AND known_text = 'can you tell me something else before I answer?' AND version = 2) THEN RAISE EXCEPTION 'CHANGED UNDER US: S seed 1250'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_legos WHERE id = '7646a985-4254-4fb4-8a21-bc293f2d8358' AND target_text = 'dw i newydd ddechrau' AND is_new = true AND version = 17) THEN RAISE EXCEPTION 'CHANGED UNDER US: N S0015L01'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_legos WHERE id = '5571feed-5325-4191-9efd-a1cd70b73995' AND target_text = 'dw i newydd ddechrau' AND is_new = true AND version = 15) THEN RAISE EXCEPTION 'CHANGED UNDER US: S S0015L01'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_legos WHERE id = 'f69255d2-da7c-4f0b-93b4-7b37015e97b9' AND lego_index = 3 AND target_text = 'cyn i mi ateb' AND version = 3) THEN RAISE EXCEPTION 'CHANGED UNDER US: N S1250L03'; END IF;
  IF EXISTS (SELECT 1 FROM course_legos WHERE course_code = 'cym_nv2_for_eng' AND seed_number = 1250 AND lego_index >= 4) THEN RAISE EXCEPTION 'N S1250L04 is taken'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_legos WHERE id = '37ce2ebb-2d4d-4031-b8a8-3419c17fd0a7' AND lego_index = 4 AND target_text = 'cyn i fi ateb' AND version = 3) THEN RAISE EXCEPTION 'CHANGED UNDER US: S S1250L04'; END IF;
  IF EXISTS (SELECT 1 FROM course_legos WHERE course_code = 'cym_sv2_for_eng' AND seed_number = 1250 AND lego_index >= 5) THEN RAISE EXCEPTION 'S S1250L05 is taken'; END IF;
  IF EXISTS (SELECT 1 FROM course_legos WHERE (course_code, seed_number, lego_index) IN (('cym_nv2_for_eng', 1250, 4), ('cym_sv2_for_eng', 1250, 5)) AND NOT is_new) THEN RAISE EXCEPTION 'cyn i … ateb is not new'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_legos WHERE course_code = 'cym_nv2_for_eng' AND seed_number = 64 AND lego_index = 1 AND is_new AND target_text = 'mae o newydd ddechrau') THEN RAISE EXCEPTION 'N newydd LEGO at seed 64 is not new'; END IF;
  IF NOT EXISTS (SELECT 1 FROM course_legos WHERE course_code = 'cym_sv2_for_eng' AND seed_number = 62 AND lego_index = 1 AND is_new AND target_text = 'ma fe newydd ddechrau') THEN RAISE EXCEPTION 'S newydd LEGO at seed 62 is not new'; END IF;
END $$;

-- The backup: every row of every touched seed (seed row, LEGOs, phrases, intros, proof flags) as it stands now.
CREATE TABLE backup_cym_newydd_wrthyn_565_seeds AS SELECT x.* FROM course_seeds x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number);
CREATE TABLE backup_cym_newydd_wrthyn_565_legos AS SELECT x.* FROM course_legos x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number);
CREATE TABLE backup_cym_newydd_wrthyn_565_phrases AS SELECT x.* FROM course_practice_phrases x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number);
CREATE TABLE backup_cym_newydd_wrthyn_565_intros AS SELECT x.* FROM lego_introductions x JOIN t_seeds t ON t.c = x.course_code AND substr(x.lego_id, 2, 4)::int = t.s;
CREATE TABLE backup_cym_newydd_wrthyn_565_flags AS SELECT x.* FROM lego_proof_flags x JOIN t_seeds t ON t.c = x.course_code AND substr(x.lego_id, 2, 4)::int = t.s;
CREATE TABLE backup_cym_newydd_wrthyn_565_touched AS SELECT * FROM t_seeds;
CREATE TABLE backup_cym_newydd_wrthyn_565_drops AS SELECT x.* FROM course_seed_weave_drops x JOIN t_seeds t ON (t.c, t.s) = (x.course_code, x.seed_number);
REVOKE ALL ON backup_cym_newydd_wrthyn_565_seeds, backup_cym_newydd_wrthyn_565_legos, backup_cym_newydd_wrthyn_565_phrases, backup_cym_newydd_wrthyn_565_intros, backup_cym_newydd_wrthyn_565_flags, backup_cym_newydd_wrthyn_565_touched, backup_cym_newydd_wrthyn_565_drops FROM anon, authenticated;

